figureDir = "figures";
if ~isfolder(figureDir)
    mkdir(figureDir);
end

opsMat = OpenSeesMatlab();
ops = opsMat.opensees;
ops.wipe();
%%
%[text] 
outdir = "openseesmatlab.output";
accFile  = "acc_value.txt";
results = liquefiableSoil2D(ops, outdir, accFile);
%[text] 
disp(results.elapsedTime); % tcl: 148.986 s %[output:17cc2aa0]
% tcl: 148.986 s
opts = opsMat.vis.defaultPlotModelOptions;
opts.mpConstraint.show = false;
opts.elements.showWireframeOnFaces = true;
opts.nodes.show = true;

opsMat.vis.plotModel(opts=opts); %[output:9ea1f434] %[output:1d791fe9]
xlabel("X","FontSize", 15); %[output:1d791fe9]
ylabel("Y","FontSize", 15); %[output:1d791fe9]
ax = gca;
% Change only Y-axis tick label font size
ax.YAxis.FontSize = 14; %[output:1d791fe9]
% Optionally, change X-axis separately
ax.XAxis.FontSize = 14; %[output:1d791fe9]

exportgraphics(ax, fullfile(figureDir, "liquefiableSoil2D_model.pdf")) %[output:1d791fe9]

