    nodeCoordinates(i, :) = double(ops.nodeCoord(nodeTags(i)));
end
modelData = table(nodeTags, nodeCoordinates(:, 1), nodeCoordinates(:, 2), ...
    'VariableNames', {'NodeTag','X_m','Y_m'});
writetable(modelData, ...
    fullfile(figureDir, "liquefiableSoil2D_model.csv"));
