%[text] 
%%
% =========================================================================
% Comparison of OpenSeesMatlab and Tcl results
%
% Comparisons:
%   1. Vertical and horizontal displacement
%   2. Horizontal acceleration response
%   3. Pore water pressure response
%
% The maximum absolute difference is displayed in each response plot.
% =========================================================================

fontName = "Times New Roman";
fontSize = 14;
lineWidth = 1.6;
axisLineWidth = 1.0;
timeLimit = [0, 33];


%% =========================================================================
%  1. Compare displacement responses
% =========================================================================

% Input files
dispFileMAT = fullfile(outdir, "disp2.txt");
dispFileTCL = fullfile("tcl", "OutPuts", "disp2.txt");

% Read recorder outputs
dispDataMAT = readmatrix(dispFileMAT);
dispDataTCL = readmatrix(dispFileTCL);
accData = readmatrix(accFile);

% Remove rows containing invalid time values
dispDataMAT = dispDataMAT(isfinite(dispDataMAT(:, 1)), :);
dispDataTCL = dispDataTCL(isfinite(dispDataTCL(:, 1)), :);

% Time vectors
timeDispMAT = dispDataMAT(:, 1);
timeDispTCL = dispDataTCL(:, 1);

% Recorder responses
% Original Python numbers_str[12] -> MATLAB column 13
% Original Python numbers_str[11] -> MATLAB column 12
dispVerticalMAT = dispDataMAT(:, 13);
dispHorizontalMAT = dispDataMAT(:, 12);

dispVerticalTCL = dispDataTCL(:, 13);
dispHorizontalTCL = dispDataTCL(:, 12);

% Input acceleration
dtAcc = 0.01;
acc = accData(:, 1);
timeAcc = (0:numel(acc)-1).' * dtAcc;

% Interpolate Tcl results to OpenSeesMatlab time points
dispVerticalTCLInterp = interp1( ...
    timeDispTCL, ...
    dispVerticalTCL, ...
    timeDispMAT, ...
    "linear", ...
    "extrap");

dispHorizontalTCLInterp = interp1( ...
    timeDispTCL, ...
    dispHorizontalTCL, ...
    timeDispMAT, ...
    "linear", ...
    "extrap");

% Calculate differences
diffVertical = dispVerticalMAT - dispVerticalTCLInterp;
diffHorizontal = dispHorizontalMAT - dispHorizontalTCLInterp;

maxDiffVertical = max(abs(diffVertical), [], "omitnan");
maxDiffHorizontal = max(abs(diffHorizontal), [], "omitnan");

rmsDiffVertical = sqrt(mean(diffVertical.^2, "omitnan"));
rmsDiffHorizontal = sqrt(mean(diffHorizontal.^2, "omitnan"));

% Print comparison results
fprintf("\nDisplacement comparison\n"); %[output:8ae6191f]
fprintf("-----------------------------------------------\n"); %[output:1eebeff4]
fprintf("Maximum absolute vertical difference   = %.6e m\n", ... %[output:group:67c75831] %[output:34d9c86c]
    maxDiffVertical); %[output:group:67c75831] %[output:34d9c86c]
fprintf("RMS vertical difference                = %.6e m\n", ... %[output:group:11f7340f] %[output:2e8710b9]
    rmsDiffVertical); %[output:group:11f7340f] %[output:2e8710b9]
fprintf("Maximum absolute horizontal difference = %.6e m\n", ... %[output:group:4cef23be] %[output:3cca941b]
    maxDiffHorizontal); %[output:group:4cef23be] %[output:3cca941b]
fprintf("RMS horizontal difference              = %.6e m\n", ... %[output:group:7ee77d3e] %[output:129417be]
    rmsDiffHorizontal); %[output:group:7ee77d3e] %[output:129417be]
%%
%[text] 
% -------------------------------------------------------------------------
% Input acceleration
% -------------------------------------------------------------------------

figure( ... %[output:21537ee1]
    "Color", "w", ... %[output:21537ee1]
    "Position", [100, 100, 900, 250]); %[output:21537ee1]
axInputAcc = gca; %[output:21537ee1]
hold(axInputAcc, "on"); %[output:21537ee1]
box(axInputAcc, "on"); %[output:21537ee1]
grid(axInputAcc, "on"); %[output:21537ee1]

plot(axInputAcc, ... %[output:21537ee1]
    timeAcc, ... %[output:21537ee1]
    acc, ... %[output:21537ee1]
    "-", ... %[output:21537ee1]
    'Color', 'Blue', ... %[output:21537ee1]
    "LineWidth", 1.2); %[output:21537ee1]

ylabel(axInputAcc, ... %[output:21537ee1]
    "Input acc. (g)", ... %[output:21537ee1]
    "FontName", fontName, ... %[output:21537ee1]
    "FontSize", fontSize); %[output:21537ee1]

xlabel(axInputAcc, ... %[output:21537ee1]
    "Time (s)", ... %[output:21537ee1]
    "FontName", fontName, ... %[output:21537ee1]
    "FontSize", fontSize); %[output:21537ee1]
% 
% title(axInputAcc, ...
%     "Input Ground Acceleration", ...
%     "FontName", fontName, ...
%     "FontSize", fontSize + 1, ...
%     "FontWeight", "normal");

xlim(axInputAcc, timeLimit); %[output:21537ee1]
ylim([-0.4 0.4]); %[output:21537ee1]

set(axInputAcc, ... %[output:21537ee1]
    "FontName", fontName, ... %[output:21537ee1]
    "FontSize", fontSize, ... %[output:21537ee1]
    "LineWidth", axisLineWidth, ... %[output:21537ee1]
    "TickDir", "in"); %[output:21537ee1]
f = gcf;
exportgraphics(f, fullfile(figureDir, "liquefiableSoil2D_inputACC.pdf")) %[output:21537ee1]
inputAccelerationData = table(timeAcc, acc, ...
