timeAccTCL = accRespDataTCL(:, 1);

% Horizontal acceleration
accMAT = accRespDataMAT(:, 2);
accTCL = accRespDataTCL(:, 2);

% Interpolate Tcl response to OpenSeesMatlab time points
accTCLInterp = interp1( ...
    timeAccTCL, ...
    accTCL, ...
    timeAccMAT, ...
    "linear", ...
    "extrap");

% Difference
diffAcc = accMAT - accTCLInterp;

maxDiffAcc = max(abs(diffAcc), [], "omitnan");
rmsDiffAcc = sqrt(mean(diffAcc.^2, "omitnan"));

% Print acceleration comparison
fprintf("\nAcceleration comparison\n"); %[output:78c19220]
fprintf("-----------------------------------------------\n"); %[output:33e5d4c2]
fprintf("Maximum absolute acceleration difference = %.6e m/s^2\n", ... %[output:group:562d7b6e] %[output:38135b77]
    maxDiffAcc); %[output:group:562d7b6e] %[output:38135b77]
fprintf("RMS acceleration difference              = %.6e m/s^2\n", ... %[output:group:630cae8c] %[output:4cfe8e2f]
