%% =========================================================================
%  3. Compare pore water pressure responses
% =========================================================================

% Input files
pwpFileMAT = fullfile(outdir, "pwp1.txt");
pwpFileTCL = fullfile("tcl", "OutPuts", "pwp1.txt");

% Read recorder outputs
pwpDataMAT = readmatrix(pwpFileMAT);
pwpDataTCL = readmatrix(pwpFileTCL);

% Remove rows containing invalid time values
pwpDataMAT = pwpDataMAT(isfinite(pwpDataMAT(:, 1)), :);
pwpDataTCL = pwpDataTCL(isfinite(pwpDataTCL(:, 1)), :);

% Time vectors
timePWPMAT = pwpDataMAT(:, 1);
timePWPTCL = pwpDataTCL(:, 1);

% Pore water pressure responses
pwpMAT = pwpDataMAT(:, 2:5);
pwpTCL = pwpDataTCL(:, 2:5);

% Interpolate Tcl responses to OpenSeesMatlab time points
pwpTCLInterp = zeros(size(pwpMAT));

for i = 1:4
    pwpTCLInterp(:, i) = interp1( ...
        timePWPTCL, ...
        pwpTCL(:, i), ...
        timePWPMAT, ...
        "linear", ...
        "extrap");
end

% Calculate differences
diffPWP = pwpMAT - pwpTCLInterp;

maxDiffPWP = max(abs(diffPWP), [], 1, "omitnan");
rmsDiffPWP = sqrt(mean(diffPWP.^2, 1, "omitnan"));

% Print comparison results
fprintf("\nPore water pressure comparison\n"); %[output:70f23e08]
fprintf("-----------------------------------------------\n"); %[output:0ab4cb9a]

for i = 1:4 %[output:group:4dd424fa]
    fprintf( ... %[output:0e06b913]
        "PWP column %d: maximum absolute difference = %.6e, RMS difference = %.6e\n", ... %[output:0e06b913]
        i, ... %[output:0e06b913]
        maxDiffPWP(i), ... %[output:0e06b913]
        rmsDiffPWP(i)); %[output:0e06b913]
end %[output:group:4dd424fa]

depthLabels = [
    "PWP (8 m)"
    "PWP (6 m)"
    "PWP (4 m)"
    "PWP (3 m)"
];

% Create pore water pressure figure
figure( ... %[output:71e17e7e]
    "Color", "w", ... %[output:71e17e7e]
    "Position", [100, 100, 900, 760]); %[output:71e17e7e]

tiledlayout(4, 1, ... %[output:71e17e7e]
    "TileSpacing", "compact", ... %[output:71e17e7e]
    "Padding", "compact"); %[output:71e17e7e]

axPWP = gobjects(4, 1);

for i = 1:4

    axPWP(i) = nexttile; %[output:71e17e7e]
    hold(axPWP(i), "on");
    box(axPWP(i), "on");
    grid(axPWP(i), "on");

    plot(axPWP(i), ...
        timePWPMAT, ...
        pwpMAT(:, i), ...
        "-", ...
        "LineWidth", lineWidth, ...
        "DisplayName", "OpenSeesMatlab");

    plot(axPWP(i), ...
        timePWPTCL, ...
        pwpTCL(:, i), ...
        "--", ...
        "LineWidth", lineWidth, ...
        "DisplayName", "OpenSeesTcl");

    ylabel(axPWP(i), ...
        depthLabels(i), ...
        "FontName", fontName, ...
        "FontSize", fontSize);

    xlim(axPWP(i), timeLimit);

    set(axPWP(i), ...
        "FontName", fontName, ...
        "FontSize", fontSize, ...
        "LineWidth", axisLineWidth, ...
        "TickDir", "in");

    if i < 4
        set(axPWP(i), "XTickLabel", []);
    else
        xlabel(axPWP(i), ...
            "Time (s)", ...
            "FontName", fontName, ...
            "FontSize", fontSize);
    end

    if i == 1
        title(axPWP(i), ...
            "Pore Water Pressure Response", ...
            "FontName", fontName, ...
            "FontSize", fontSize + 1, ...
            "FontWeight", "normal");

        legend(axPWP(i), ...
            "Location", "northeast", ...
            "Box", "off", ...
